window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4aeb8a55ea6fba31"]={"versions": [{"id": "FIG-4aeb8a55ea6fba31", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Wrapper-Funktion <code>E2EPW_Read2</code> (E2E Protection Wrapper) innerhalb der AUTOSAR E2E-Bibliothek (Classic Platform). Das Diagramm spezifiziert den sequenziellen Ablauf von Parametervalidierung, Deserialisierungsprüfung, Datenaufbereitung, E2E-Prüffunktionsaufruf und Ergebnisaggregation beim Empfang von Daten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Eingangs- und Zustandsdaten:\n<ul class=\"fig-list\"><li><code>AppDataEl</code>: Zeiger auf das zu lesende Anwendungs-Datenelement.\n</li><li><code>Config2</code>: Zeiger auf die E2E-Konfigurationsstruktur des geschützten Datenkanals.\n</li><li><code>State2</code>: Zeiger auf die E2E-Zustandsstruktur mit Feldern <code>NewDataAvailable</code> und <code>Status</code>.\n</li><li><code>Data</code>: PDU-Repräsentation (Rohdaten-Byte-Array) für die E2E-Prüfung.\n</li></ul>\n</li><li>Lokale Variablen und Statuswerte:\n<ul class=\"fig-list\"><li><code>retRteRead</code>: Rückgabewert des RTE-Leseaufrufs, initialisiert mit <code>RTE_E_OK</code>.\n</li><li><code>plausibilityChecks</code>: Plausibilitätsstatus, initialisiert mit <code>E2E_E_OK</code>; mögliche Fehlerwerte sind <code>E2E_E_INPUTERR_NULL</code> und <code>E2EPW_E_DESERIALIZATION</code>.\n</li><li><code>retE2ECheck</code>: Ergebnis des E2E-Profilprüfaufrufs, initialisiert mit <code>E2E_E_OK</code>.\n</li><li><code>ret</code>: Zusammengesetzter 32-Bit-Rückgabewert der Funktion.\n</li></ul>\n</li><li>Funktionen und Aktionen:\n<ul class=\"fig-list\"><li><code>Check deserialization of AppDataEl</code>: Prüfung der Gültigkeit des deserialisierten Datenelements.\n</li><li><code>SerializeAppDataEl to IPDU representation Data...</code>: Transformation/Serialisierung in die Byte-Array-Darstellung <code>Data</code>.\n</li><li><code>E2E_PXXCheck(Config2, State2, Data)</code>: Profilspezifische E2E-Prüffunktion der E2E Library.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten; Initialisierung von <code>retRteRead = RTE_E_OK</code>, <code>plausibilityChecks = E2E_E_OK</code> und <code>retE2ECheck = E2E_E_OK</code>.\n</li><li>Verzweigung an Guard <code>AppDataEl == NULL</code>:\n<ul class=\"fig-list\"><li>[TRUE]: Zuweisung <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>, anschließender Übergang direkt zum Merge-Knoten vor der Rückgabewert-Zusammensetzung.\n</li><li>[FALSE]: Zuweisung <code>State2-&gt;NewDataAvailable = TRUE</code>.\n</li></ul>\n</li><li>Ausführung der Aktion <code>Check deserialization of AppDataEl</code> und nachfolgende Verzweigung <code>Deserialization invalid?</code>:\n<ul class=\"fig-list\"><li>[TRUE]: Zuweisung <code>plausibilityChecks = E2EPW_E_DESERIALIZATION</code>, anschließender Übergang zum Merge-Knoten.\n</li><li>[FALSE]: Ausführung der Aktion zur Serialisierung von <code>AppDataEl</code> in die IPDU-Darstellung <code>Data</code> (sofern es sich um ein komplexes Datenelement handelt; andernfalls Kopieren des Byte-Arrays nach <code>Data</code>).\n</li></ul>\n</li><li>Aufruf von <code>retE2ECheck = E2E_PXXCheck(Config2, State2, Data)</code> und Übergang zum Merge-Knoten.\n</li><li>Zusammenführung der drei Kontrollflusspfade am Merge-Knoten.\n</li><li>Bitweise Zusammensetzung des 32-Bit-Gesamtrückgabewerts:\n <code>ret = ((retRteRead) | (retE2ECheck &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16) | (State2-&gt;Status &lt;&lt; 24))</code>.\n</li><li>Beendigung am Endknoten mit Rückgabe von <code>ret</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Ablaufverhalten für generierte E2E-Protection-Wrapper bei Leseoperationen vom Typ 2:</p>\n<ul class=\"fig-list\"><li>Vor jeglicher Verarbeitung muss der Zeiger <code>AppDataEl</code> auf <code>NULL</code> geprüft werden, um Nullzeiger-Dereferenzierungen zu verhindern.\n</li><li>Im Fehlerfall (<code>AppDataEl == NULL</code> oder ungültige Deserialisierung) wird der E2E-Prüfaufruf <code>E2E_PXXCheck</code> übersprungen und stattdessen ein determinierter Plausibilitätsfehlercode gesetzt.\n</li><li>Komplexe Datenelemente müssen vor Übergabe an die E2E-Prüffunktion zwingend in das kanonische PDU-Layout serialisiert werden, da die E2E-Prüffunktionen ausschließlich auf linearisierten Rohdaten-Puffern operieren.\n</li><li>Der aggregierte Rückgabewert kodiert vier separate 8-Bit-Statusinformationen (RTE-Status, E2E-Check-Ergebnis, Plausibilitätsprüfungsstatus und E2E-Zustandsmaschinenstatus) in einem standardisierten 32-Bit-Wort.\n</li></ul>"}, {"id": "FIG-959eb01de36bc915", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Wrapper-Funktion <code>E2EPW_Read2</code> (E2E Protection Wrapper) innerhalb der AUTOSAR E2E-Bibliothek (Classic Platform). Das Diagramm spezifiziert den sequenziellen Ablauf von Parametervalidierung, Deserialisierungsprüfung, Datenaufbereitung, E2E-Prüffunktionsaufruf und Ergebnisaggregation beim Empfang von Daten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Eingangs- und Zustandsdaten:\n<ul class=\"fig-list\"><li><code>AppDataEl</code>: Zeiger auf das zu lesende Anwendungs-Datenelement.\n</li><li><code>Config2</code>: Zeiger auf die E2E-Konfigurationsstruktur des geschützten Datenkanals.\n</li><li><code>State2</code>: Zeiger auf die E2E-Zustandsstruktur mit Feldern <code>NewDataAvailable</code> und <code>Status</code>.\n</li><li><code>Data</code>: PDU-Repräsentation (Rohdaten-Byte-Array) für die E2E-Prüfung.\n</li></ul>\n</li><li>Lokale Variablen und Statuswerte:\n<ul class=\"fig-list\"><li><code>retRteRead</code>: Rückgabewert des RTE-Leseaufrufs, initialisiert mit <code>RTE_E_OK</code>.\n</li><li><code>plausibilityChecks</code>: Plausibilitätsstatus, initialisiert mit <code>E2E_E_OK</code>; mögliche Fehlerwerte sind <code>E2E_E_INPUTERR_NULL</code> und <code>E2EPW_E_DESERIALIZATION</code>.\n</li><li><code>retE2ECheck</code>: Ergebnis des E2E-Profilprüfaufrufs, initialisiert mit <code>E2E_E_OK</code>.\n</li><li><code>ret</code>: Zusammengesetzter 32-Bit-Rückgabewert der Funktion.\n</li></ul>\n</li><li>Funktionen und Aktionen:\n<ul class=\"fig-list\"><li><code>Check deserialization of AppDataEl</code>: Prüfung der Gültigkeit des deserialisierten Datenelements.\n</li><li><code>SerializeAppDataEl to IPDU representation Data...</code>: Transformation/Serialisierung in die Byte-Array-Darstellung <code>Data</code>.\n</li><li><code>E2E_PXXCheck(Config2, State2, Data)</code>: Profilspezifische E2E-Prüffunktion der E2E Library.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten; Initialisierung von <code>retRteRead = RTE_E_OK</code>, <code>plausibilityChecks = E2E_E_OK</code> und <code>retE2ECheck = E2E_E_OK</code>.\n</li><li>Verzweigung an Guard <code>AppDataEl == NULL</code>:\n<ul class=\"fig-list\"><li>[TRUE]: Zuweisung <code>plausibilityChecks = E2E_E_INPUTERR_NULL</code>, anschließender Übergang direkt zum Merge-Knoten vor der Rückgabewert-Zusammensetzung.\n</li><li>[FALSE]: Zuweisung <code>State2-&gt;NewDataAvailable = TRUE</code>.\n</li></ul>\n</li><li>Ausführung der Aktion <code>Check deserialization of AppDataEl</code> und nachfolgende Verzweigung <code>Deserialization invalid?</code>:\n<ul class=\"fig-list\"><li>[TRUE]: Zuweisung <code>plausibilityChecks = E2EPW_E_DESERIALIZATION</code>, anschließender Übergang zum Merge-Knoten.\n</li><li>[FALSE]: Ausführung der Aktion zur Serialisierung von <code>AppDataEl</code> in die IPDU-Darstellung <code>Data</code> (sofern es sich um ein komplexes Datenelement handelt; andernfalls Kopieren des Byte-Arrays nach <code>Data</code>).\n</li></ul>\n</li><li>Aufruf von <code>retE2ECheck = E2E_PXXCheck(Config2, State2, Data)</code> und Übergang zum Merge-Knoten.\n</li><li>Zusammenführung der drei Kontrollflusspfade am Merge-Knoten.\n</li><li>Bitweise Zusammensetzung des 32-Bit-Gesamtrückgabewerts:\n <code>ret = ((retRteRead) | (retE2ECheck &lt;&lt; 8) | (plausibilityChecks &lt;&lt; 16) | (State2-&gt;Status &lt;&lt; 24))</code>.\n</li><li>Beendigung am Endknoten mit Rückgabe von <code>ret</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Ablaufverhalten für generierte E2E-Protection-Wrapper bei Leseoperationen vom Typ 2:</p>\n<ul class=\"fig-list\"><li>Vor jeglicher Verarbeitung muss der Zeiger <code>AppDataEl</code> auf <code>NULL</code> geprüft werden, um Nullzeiger-Dereferenzierungen zu verhindern.\n</li><li>Im Fehlerfall (<code>AppDataEl == NULL</code> oder ungültige Deserialisierung) wird der E2E-Prüfaufruf <code>E2E_PXXCheck</code> übersprungen und stattdessen ein determinierter Plausibilitätsfehlercode gesetzt.\n</li><li>Komplexe Datenelemente müssen vor Übergabe an die E2E-Prüffunktion zwingend in das kanonische PDU-Layout serialisiert werden, da die E2E-Prüffunktionen ausschließlich auf linearisierten Rohdaten-Puffern operieren.\n</li><li>Der aggregierte Rückgabewert kodiert vier separate 8-Bit-Statusinformationen (RTE-Status, E2E-Check-Ergebnis, Plausibilitätsprüfungsstatus und E2E-Zustandsmaschinenstatus) in einem standardisierten 32-Bit-Wort.\n</li></ul>"}], "trans": [{"from": "FIG-4aeb8a55ea6fba31", "to": "FIG-959eb01de36bc915", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
